# -*- coding: utf-8 -*-

# Author: Rensc
# Date: 2026-06-12
# Version: 0.2.7
# Function: Run the RiboParser command for RiboParser.
# Input: Function parameters and intermediate RiboParser data objects.
# Output: Processed data objects or output files generated by module functions.

from importlib.metadata import PackageNotFoundError
from importlib.metadata import version as package_version
from pathlib import Path
import importlib
import subprocess
import sys


def get_package_version(package_name: str = "RiboParser") -> str:
    """
    Get the installed package version from Python package metadata.

    Returns
    -------
    str
        Package version, or "unknown" if RiboParser is not installed as a package.
    """
    try:
        return package_version(package_name)
    except PackageNotFoundError:
        return "unknown"


def find_project_root(start_path: Path | None = None) -> Path:
    """
    Find the project root directory.

    The project root is identified by common project markers:
    pyproject.toml, README.md, .git, utils, or scripts.

    Parameters
    ----------
    start_path : Path | None
        Starting path for searching. If None, use this file path.

    Returns
    -------
    Path
        Detected project root directory.
    """
    if start_path is None:
        start_path = Path(__file__).resolve()

    root = start_path.parent

    for _ in range(10):
        if any(
            (root / name).exists()
            for name in ("pyproject.toml", "README.md", ".git", "utils", "scripts")
        ):
            return root

        if root.parent == root:
            break

        root = root.parent

    return Path(__file__).resolve().parent


def run_git_command(root: Path, args: list[str]) -> str:
    """
    Run a git command in the project root.

    Parameters
    ----------
    root : Path
        Project root directory.
    args : list[str]
        Git command arguments.

    Returns
    -------
    str
        Command output. Return "unknown" if git command fails.
    """
    try:
        result = subprocess.run(
            ["git", "-C", str(root), *args],
            check=True,
            capture_output=True,
            text=True,
        )
        output = result.stdout.strip()
        return output if output else "unknown"
    except Exception:
        return "unknown"


def get_git_commit_date() -> str:
    """
    Get the latest git commit date from the current source checkout.

    This works when RiboParser is run from a cloned GitHub repository.
    If the package is installed from wheel or copied without .git metadata,
    this function returns "unknown".

    Returns
    -------
    str
        Latest commit date in YYYY-MM-DD format, or "unknown".
    """
    root = find_project_root()
    return run_git_command(root, ["log", "-1", "--format=%cs"])


def get_git_commit_hash() -> str:
    """
    Get the latest git commit hash from the current source checkout.

    Returns
    -------
    str
        Short commit hash, or "unknown".
    """
    root = find_project_root()
    return run_git_command(root, ["rev-parse", "--short", "HEAD"])


def get_update_date() -> str:
    """
    Get the update date of the current RiboParser source.

    Priority:
    1. Generated build metadata: utils.data._build_info.__commit_date__
    2. Git latest commit date from local source checkout
    3. "unknown"

    Returns
    -------
    str
        Update date in YYYY-MM-DD format, or "unknown".
    """
    try:
        from utils.data._build_info import __commit_date__

        if __commit_date__ and __commit_date__ != "unknown":
            return __commit_date__
    except Exception:
        pass

    return get_git_commit_date()


class RiboParserInfo:
    version = get_package_version()
    update_date = get_update_date()
    commit = get_git_commit_hash()

    citation = """
Shuchao Ren, Yinan Li, Zhipeng Zhou.
RiboParser/RiboShiny: An integrated platform for comprehensive analysis and
visualization of ribo-seq data.
Journal of Genetics and Genomics (2025)
doi:10.1016/j.jgg.2025.04.010.
"""

    required_packages = [
        "pandas",
        "polars",
        "numpy",
        "matplotlib-venn",
        "seqlogo",
        "matplotlib",
        "seaborn",
        "biopython",
        "scipy",
        "scikit-learn",
        "statsmodels",
        "pysam",
        "joblib",
    ]

    @classmethod
    def show_version(cls):
        print(f"RiboParser version: {cls.version}")
        print(f"Last update: {cls.update_date}")

        if cls.commit != "unknown":
            print(f"Git commit: {cls.commit}")

    @classmethod
    def show_citation(cls):
        print("Please cite:")
        print(cls.citation)

    @classmethod
    def check_dependencies(cls):
        missing = []

        for pkg in cls.required_packages:
            try:
                package_version(pkg)
            except PackageNotFoundError:
                missing.append(pkg)

        if missing:
            print(f"Missing dependencies: {', '.join(missing)}")
            return False

        print(cls.required_packages)
        print("All required dependencies are installed.")
        return True

    @classmethod
    def check_package_modules(cls, module_type: str = "all"):
        script_path = Path(__file__).resolve()
        root = find_project_root(script_path)

        if str(root) not in sys.path:
            sys.path.insert(0, str(root))

        utils_dir = root / "utils"
        scripts_dir = root / "scripts"

        modules = {
            "ribo": [],
            "serp": [],
            "smorf": [],
            "scripts": [],
        }

        def module_name_from_path(p: Path) -> str:
            rel = p.relative_to(root)
            return ".".join(rel.with_suffix("").parts)

        def add_module(p: Path):
            if p.name.startswith("_") or p.name == "__init__.py":
                return

            mod = module_name_from_path(p)
            parts = p.relative_to(root).parts
            stem = p.stem

            if "smorf" in parts or stem.startswith("smorf_"):
                modules["smorf"].append(mod)
            elif "serp" in parts or stem.startswith("serp_"):
                modules["serp"].append(mod)
            elif "ribo" in parts or stem.startswith(("rpf_", "rna_")):
                modules["ribo"].append(mod)
            elif "scripts" in parts:
                modules["scripts"].append(mod)

        if utils_dir.exists():
            for p in utils_dir.rglob("*.py"):
                add_module(p)

        if scripts_dir.exists():
            for p in scripts_dir.rglob("*.py"):
                add_module(p)

        for key in modules:
            modules[key] = sorted(set(modules[key]))

        def try_import(module_name: str) -> bool:
            try:
                importlib.import_module(module_name)
                return True
            except Exception:
                return False

        show_keys = modules.keys() if module_type == "all" else [module_type]

        for key in show_keys:
            print(f"{key} modules:")

            if modules.get(key):
                for mod in modules[key]:
                    status = "[import OK]" if try_import(mod) else "[import FAILED]"
                    print(f" - {mod} {status}")
            else:
                print(" - (not found)")
